public container registerMenu()
{
    container ret = [['MoveMultiLicensePlates', "@MobileWMS:MoveMultipleLicensePlates", true, resourceStr(MobPalletMoveIcon)]];

    return ret;
}

	[TFMReferenceDataMethod]
    public TFMReferenceDataConfiguration MoveMultipleLicensePlatesFilter()
    {
        TFMReferenceDataConfiguration refData = new TFMReferenceDataConfiguration();
        TFMRegistrationCollectorList  warehouse = TFMGetReferenceData::createDefaultWarehouseReferenceData(1);
        refData.addCollector(warehouse);

        return refData;
    }

public Map addTranslations()
{
    Map ret;

    ret = super();
    ret.insert('MoveMultipleLicensePlates', "@MobileWMS:MoveMultipleLicensePlates");

    return ret;
}

[TFMCollectorMap(classStr(TFMGetRegistrationConfiguration), 'MoveMultiLicensePlates'), TFMCollectorConfigurationAdditionalAttribute('cancelBehaviour', 'Warn')]
public Map MoveMultipleLicensePlatesPrompt()
{
    Map										returnMap = new Map(Types::String,Types::Class);
    TFMRegistrationCollectorTypeAndQuantity licensePlates = new TFMRegistrationCollectorTypeAndQuantity(1,extendedTypeStr(WHSLicensePlateId),"@WAX67","@WAX67","@WAX67");
    TFMRegistrationCollectorText			Location = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WMSLocationId));      
    Location.parmId(20);

    licensePlates.parmUniqueValues(true);
    licensePlates.setOnlineValidationDocument(methodStr(MobOnlineValidator, LicensePlateValidation));

    returnMap.insert(extendedTypeStr(WHSLicensePlateId),licensePlates.getMap());
    returnMap.insert(extendedTypeStr(WMSLocationId),Location.getMap());

    return returnMap;
}

[TFMDocumentType(classStr(TFMPostAdhocRegistration),'MoveMultiLicensePlates')]
public void MoveMultipleLicensePlatesPost()
{
    str					lps		= request.getFieldValue(extendedTypeStr(WHSLicensePlateId));
    WMSLocationId		locId	= request.getFieldValue(extendedTypeStr(WMSLocationId));
    InventLocationId	whs		= request.getFieldValue(MobConstants::Warehouse());
    ListEnumerator		lpList	= strSplit(lps,';').getEnumerator();
    WhsLicensePlateId	lpToMove;

    if (!WMSLocation::exist(locId,whs))
    {
        throw Error (strFmt("@SYS53781",locId,whs));
    }

    while(lpList.moveNext())
    {
        lpToMove = subStr(lpList.current(),1,strScan(lpList.current(),'=',1,100)-1);
        MobPostHelper::MoveLicensePlate(lpToMove,whs,locId);
    }
}
